function Stars({ rating }) {
  return (
    <div style={{ display: "flex", gap: 2 }}>
      {Array.from({ length: 5 }, (_, i) => (
        <span
          key={i}
          style={{
            fontSize: 16,
            color: i < rating ? "#e8a020" : "#ddd",
            lineHeight: 1,
          }}
        >
          ★
        </span>
      ))}
    </div>
  );
}

